def transform(grid):
    out=[r[:] for r in grid]
    bg=grid[0][0]
    # Each row containing alternating foreground markers gets color 2 in gaps between markers.
    # Identify color different from background and fill intervening horizontal gaps.
    for i,row in enumerate(grid):
        inds=[j for j,v in enumerate(row) if v!=bg]
        if len(inds)>=2:
            for a,b in zip(inds,inds[1:]):
                if b-a==2 and all(row[k]==bg for k in range(a+1,b)):
                    out[i][a+1]=2
    return out
